#include "wsounddoppler89.h"
wsound89_result wsounddoppler89_init(wsounddoppler89_context*c){if(!c)return WSOUND89_EINVAL;c->phase_q16=0;c->ratio_q16=65536U;return WSOUND89_OK;}
wsound89_result wsounddoppler89_set_motion(wsounddoppler89_context*c,wsound89_i32 source_toward,wsound89_i32 listener_toward,wsound89_u32 speed){wsound89_i32 num,den,r;if(!c||speed<100U)return WSOUND89_EINVAL;num=(wsound89_i32)speed+listener_toward;den=(wsound89_i32)speed-source_toward;if(den<(wsound89_i32)(speed/4U))den=(wsound89_i32)(speed/4U);r=(num*65536)/den;if(r<32768)r=32768;if(r>131072)r=131072;c->ratio_q16=(wsound89_u32)r;return WSOUND89_OK;}void wsounddoppler89_set_ratio(wsounddoppler89_context*c,wsound89_u32 r){if(c){if(r<32768U)r=32768U;if(r>131072U)r=131072U;c->ratio_q16=r;}}
wsound89_i16 wsounddoppler89_process_buffer(wsounddoppler89_context*c,const wsound89_i16*s,wsound89_u32 frames,int*active){wsound89_u32 i,f;wsound89_i32 a,b,v;if(!c||!s||frames<2){if(active)*active=0;return 0;}i=c->phase_q16>>16;if(i+1U>=frames){if(active)*active=0;return 0;}f=c->phase_q16&65535U;a=s[i];b=s[i+1U];v=a+(((b-a)*(wsound89_i32)f)>>16);c->phase_q16+=c->ratio_q16;if(active)*active=1;return(wsound89_i16)v;}
